const TABS = ["All", "Pending", "Accepted", "Rejected"];

function Timeline({ steps, status }) {
  return (
    <div className="space-y-4">
      {steps.map((step, i) => {
        const isLast = i === steps.length - 1;
        const isRefused = status === "rejected" && i === 2 && step.done;
        const isDone = step.done && !isRefused;
        return (
          <div key={i} className="flex gap-3">
            <div className="flex flex-col items-center">
              <div className={`w-7 h-7 rounded-full flex items-center justify-center text-xs font-bold border-2 shrink-0 transition-all ${
                isRefused ? "bg-red-500 border-red-500 text-white"
                : isDone ? "bg-blue-600 border-blue-600 text-white"
                : "bg-white border-slate-200 text-slate-300"
              }`}>
                {isRefused ? "✕" : isDone ? "✓" : String(i + 1)}
              </div>
              {!isLast && (
                <div className={`w-0.5 h-6 mt-1 rounded-full ${isDone && !isRefused ? "bg-blue-200" : "bg-slate-100"}`} />
              )}
            </div>
            <div className="pb-2">
              <div className={`text-sm font-semibold ${isRefused ? "text-red-600" : isDone ? "text-slate-800" : "text-slate-400"}`}>
                {step.label}
              </div>
              <div className="text-[10px] text-slate-400">{step.date}</div>
            </div>
          </div>
        );
      })}
    </div>
  );
}
function AgreementModal({ app, agreement, onClose }) {
  const [generating, setGenerating] = useState(false);
  const [generated, setGenerated] = useState(false);

  const generate = () => {
    setGenerating(true);
    setTimeout(() => { setGenerating(false); setGenerated(true); }, 1500);
  };

  return (
    <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-50 flex items-center justify-center p-4" onClick={onClose}>
      <div className="bg-white rounded-3xl w-full max-w-md p-6 shadow-2xl" onClick={e => e.stopPropagation()}>
        {!generated ? (
          <>
            <div className="flex items-center gap-3 mb-6">
              <div className="w-12 h-12 bg-blue-50 rounded-2xl flex items-center justify-center text-2xl shrink-0">📜</div>
              <div>
                <h3 className="font-bold text-slate-900 text-lg">Convention de Stage</h3>
                <p className="text-[10px] text-blue-600 font-mono">InternshipAgreement.generatePDF()</p>
              </div>
            </div>

            <div className="bg-slate-50 border border-slate-100 rounded-2xl p-4 mb-6 space-y-3">
               {[
                  { label: "Student", value: "Amira Benali" },
                  { label: "Company", value: app.company },
                  { label: "Start date", value: agreement.startDate },
                  { label: "End date", value: agreement.endDate },
                  { label: "Reference", value: agreement.ref }
               ].map((item, idx) => (
                  <div key={idx} className="flex justify-between text-sm">
                    <span className="text-slate-500">{item.label}</span>
                    <span className="font-semibold text-slate-800">{item.value}</span>
                  </div>
               ))}
            </div>

            <button
              onClick={generate}
              disabled={generating}
              className="w-full bg-blue-600 hover:bg-blue-700 text-white font-semibold py-3.5 rounded-xl text-sm flex items-center justify-center gap-2 transition-all"
            >
              {generating ? "Generating PDF..." : "📄 Download Convention"}
            </button>
            <button onClick={onClose} className="w-full mt-3 text-sm text-slate-400 hover:text-slate-600 transition-colors">Close</button>
          </>
        ) : (
          <div className="text-center py-6">
            <div className="text-5xl mb-4">🎉</div>
            <h3 className="font-bold text-slate-900 text-xl mb-2">Ready to Download!</h3>
            <p className="text-sm text-slate-500 mb-6">Your official agreement has been generated.</p>
            <button className="w-full bg-green-600 text-white font-semibold py-3 rounded-xl mb-3">⬇ Download Now</button>
            <button onClick={onClose} className="text-sm text-slate-400">Done</button>
          </div>
        )}
      </div>
    </div>
  );
}

export default function StudentApplications() {
  const [tab, setTab] = useState("All");
  const [selected, setSelected] = useState(APPLICATIONS[1]);
  const [modal, setModal] = useState(false);

  const filtered = tab === "All" ? APPLICATIONS : APPLICATIONS.filter(a => STATUS_MAP[a.status].label === tab);
  const agreement = selected ? AGREEMENTS[selected.id] : null;

  return (
    <StudentLayout active="applications">
      <div className="p-5 md:p-8 max-w-6xl mx-auto">
        <div className="mb-8">
          <h1 className="font-bold text-slate-900 text-2xl md:text-3xl">My applications</h1>
          <p className="text-slate-400 text-sm mt-1">Track your internship requests and agreements.</p>
        </div>

        <div className="flex gap-2 mb-6 overflow-x-auto pb-2">
          {TABS.map(t => (
            <button key={t} onClick={() => setTab(t)} 
              className={`px-5 py-2 rounded-xl text-sm font-semibold transition-all shrink-0 ${tab === t ? "bg-blue-600 text-white" : "bg-white text-slate-500 border border-slate-100"}`}>
              {t}
            </button>
          ))}
        </div>
        <div className="grid lg:grid-cols-5 gap-6">
          {/* List */}
          <div className="lg:col-span-2 space-y-3">
            {filtered.map(app => (
              <div key={app.id} onClick={() => setSelected(app)}
                className={`p-4 rounded-2xl cursor-pointer border transition-all ${selected?.id === app.id ? "bg-blue-50 border-blue-200" : "bg-white border-slate-100 hover:border-blue-100"}`}>
                <div className="flex justify-between items-start mb-2">
                  <div className="text-2xl">{app.logo}</div>
                  <span className={`text-[10px] px-2 py-0.5 rounded-full font-bold uppercase ${STATUS_MAP[app.status].badge}`}>
                    {STATUS_MAP[app.status].label}
                  </span>
                </div>
                <h3 className="font-bold text-slate-800 text-sm">{app.role}</h3>
                <p className="text-xs text-slate-400 mb-3">{app.company}</p>
                <div className="flex gap-1.5 flex-wrap">
                   {app.skills.slice(0, 2).map(s => <span key={s} className="text-[10px] bg-slate-100 text-slate-600 px-2 py-0.5 rounded-md">{s}</span>)}
                </div>
              </div>
            ))}
          </div>

          {/* Details */}
          <div className="lg:col-span-3">
            {selected ? (
              <div className="bg-white border border-slate-100 rounded-3xl p-6 sticky top-8 shadow-sm">
                <div className="flex items-center gap-4 mb-6">
                   <div className="w-16 h-16 bg-slate-50 rounded-2xl flex items-center justify-center text-3xl">{selected.logo}</div>
                   <div>
                      <h2 className="font-bold text-xl text-slate-900">{selected.role}</h2>
                      <p className="text-slate-500">{selected.company}</p>
                   </div>
                </div>

                <div className={`p-4 rounded-2xl mb-6 flex items-center gap-3 text-sm ${STATUS_MAP[selected.status].badge}`}>
                   <span>{STATUS_MAP[selected.status].icon}</span>
                   {STATUS_MAP[selected.status].msg}
                </div>

                <div className="grid grid-cols-2 gap-3 mb-8">
                  {[
                    { k: "Location", v: `${selected.wilaya} · ${selected.type} `},
                    { k: "Duration", v: selected.duration },
                    { k: "Applied", v: selected.appliedDate },
                    { k: "Status", v: STATUS_MAP[selected.status].label }
                  ].map((item, i) => (
                    <div key={i} className="bg-slate-50 p-3 rounded-xl border border-slate-100">
                      <p className="text-[10px] text-slate-400 uppercase font-bold">{item.k}</p>
                      <p className="text-sm font-semibold text-slate-700">{item.v}</p>
                    </div>
                  ))}
                </div>

                <div className="mb-8">
                  <h4 className="text-xs font-bold text-slate-400 uppercase mb-4 tracking-wider">Application Journey</h4>
                  <Timeline steps={selected.timeline} status={selected.status} />
                </div>

                {selected.status === "accepted" && agreement && (
                  <div className="pt-6 border-t border-slate-100">
                    <button onClick={() => setModal(true)} 
                      className="w-full bg-blue-600 hover:bg-blue-700 text-white font-bold py-4 rounded-2xl shadow-lg shadow-blue-100 transition-all flex items-center justify-center gap-3">
                      📄 Generate Internship Agreement
                    </button>
                  </div>
                )}
              </div>
            ) : (
              <div className="h-64 border-2 border-dashed border-slate-100 rounded-3xl flex flex-col items-center justify-center text-slate-300">
                <div className="text-4xl mb-2">🖱️</div>
                <p>Select an application</p>
              </div>
            )}
          </div>
        </div>
      </div>
      {modal && selected && agreement && (
        <AgreementModal app={selected} agreement={agreement} onClose={() => setModal(false)} />
      )}
    </StudentLayout>
  );
}
